PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, auth_subject TEXT UNIQUE, email TEXT UNIQUE, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')), moodle_site TEXT, moodle_user_id INTEGER, generation INTEGER NOT NULL DEFAULT 0, created TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(moodle_site,moodle_user_id));
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, device_id TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id,expires);
CREATE TABLE IF NOT EXISTS auth_attempts (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL, claimed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS auth_limits (id TEXT PRIMARY KEY, n INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attendance_pairings (id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL, claimed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind TEXT NOT NULL, target TEXT NOT NULL DEFAULT '', generation INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', due INTEGER NOT NULL, lease TEXT, lease_until INTEGER, attempts INTEGER NOT NULL DEFAULT 0, error TEXT, UNIQUE(user_id,kind,target));
CREATE INDEX IF NOT EXISTS jobs_due ON jobs(status,due);
CREATE TABLE IF NOT EXISTS user_leases (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, token TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS user_settings (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, key TEXT NOT NULL, value TEXT NOT NULL, PRIMARY KEY(user_id,key));
CREATE TABLE IF NOT EXISTS tasks (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, id TEXT NOT NULL, course TEXT NOT NULL, title TEXT NOT NULL, due TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', source TEXT NOT NULL DEFAULT 'manual', url TEXT, reminder_minutes INTEGER NOT NULL DEFAULT 120, remind_at INTEGER, PRIMARY KEY(user_id,id));
CREATE TABLE IF NOT EXISTS classes (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, id TEXT NOT NULL, course TEXT NOT NULL, kind TEXT NOT NULL, starts TEXT NOT NULL, ends TEXT NOT NULL, room TEXT, occ TEXT, source TEXT NOT NULL DEFAULT 'manual', reminder_minutes INTEGER NOT NULL DEFAULT 15, remind_at INTEGER, PRIMARY KEY(user_id,id));
CREATE TABLE IF NOT EXISTS updates (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, id TEXT NOT NULL, course TEXT, title TEXT NOT NULL, body TEXT, url TEXT, kind TEXT, changed TEXT NOT NULL, seen INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,id));
CREATE TABLE IF NOT EXISTS snapshots (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, id TEXT NOT NULL, hash TEXT NOT NULL, PRIMARY KEY(user_id,id));
CREATE TABLE IF NOT EXISTS subscriptions (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, id TEXT NOT NULL, value TEXT NOT NULL, device_id TEXT, UNIQUE(id), PRIMARY KEY(user_id,id));
CREATE TABLE IF NOT EXISTS deliveries (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, id TEXT NOT NULL, subscription_id TEXT NOT NULL, payload TEXT NOT NULL, due TEXT NOT NULL, sent TEXT, attempts INTEGER NOT NULL DEFAULT 0, error TEXT, lease TEXT, lease_until INTEGER, PRIMARY KEY(user_id,id), FOREIGN KEY(user_id,subscription_id) REFERENCES subscriptions(user_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS semesters (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, id TEXT NOT NULL, definition TEXT NOT NULL, revision INTEGER NOT NULL, PRIMARY KEY(user_id,id));
CREATE TABLE IF NOT EXISTS class_occurrences (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, class_id TEXT NOT NULL, semester_id TEXT NOT NULL, series_id TEXT NOT NULL, date TEXT NOT NULL, overridden INTEGER NOT NULL DEFAULT 0, cancelled INTEGER NOT NULL DEFAULT 0, UNIQUE(user_id,semester_id,series_id,date), PRIMARY KEY(user_id,class_id), FOREIGN KEY(user_id,semester_id) REFERENCES semesters(user_id,id));
CREATE TABLE IF NOT EXISTS content_scopes (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, id TEXT NOT NULL, course TEXT NOT NULL, allowed INTEGER NOT NULL, parent_id TEXT, PRIMARY KEY(user_id,id));
CREATE TABLE IF NOT EXISTS update_scopes (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, update_id TEXT NOT NULL, scope_id TEXT NOT NULL, PRIMARY KEY(user_id,update_id), FOREIGN KEY(user_id,update_id) REFERENCES updates(user_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS attendance_sessions (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, id TEXT NOT NULL, course TEXT NOT NULL, course_id INTEGER NOT NULL, cmid INTEGER NOT NULL, name TEXT NOT NULL, row_key TEXT NOT NULL, day TEXT NOT NULL, label TEXT NOT NULL, session_id INTEGER, recorded TEXT NOT NULL DEFAULT '', manual INTEGER NOT NULL DEFAULT 0, checked TEXT NOT NULL, confirmed_class TEXT, class_starts TEXT, class_ends TEXT, attempted TEXT, notified INTEGER NOT NULL DEFAULT 0, message TEXT NOT NULL DEFAULT '', PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS tasks_reminders ON tasks(remind_at) WHERE status NOT IN ('done','submitted');
CREATE INDEX IF NOT EXISTS classes_reminders ON classes(remind_at);
CREATE INDEX IF NOT EXISTS tasks_owner_due ON tasks(user_id,due);
CREATE INDEX IF NOT EXISTS classes_owner_starts ON classes(user_id,starts);
CREATE INDEX IF NOT EXISTS updates_owner_changed ON updates(user_id,changed);
CREATE INDEX IF NOT EXISTS deliveries_due ON deliveries(sent,due);
CREATE INDEX IF NOT EXISTS occurrences_semester ON class_occurrences(user_id,semester_id);
CREATE INDEX IF NOT EXISTS scopes_course ON content_scopes(user_id,course);
CREATE INDEX IF NOT EXISTS attendance_owner_day ON attendance_sessions(user_id,day);
CREATE TRIGGER IF NOT EXISTS tasks_remind_insert AFTER INSERT ON tasks BEGIN UPDATE tasks SET remind_at=CAST((julianday(NEW.due)-2440587.5)*86400000 AS INTEGER)-NEW.reminder_minutes*60000 WHERE user_id=NEW.user_id AND id=NEW.id; END;
CREATE TRIGGER IF NOT EXISTS tasks_remind_update AFTER UPDATE OF due,reminder_minutes,status ON tasks BEGIN UPDATE tasks SET remind_at=CAST((julianday(NEW.due)-2440587.5)*86400000 AS INTEGER)-NEW.reminder_minutes*60000 WHERE user_id=NEW.user_id AND id=NEW.id; END;
CREATE TRIGGER IF NOT EXISTS classes_remind_insert AFTER INSERT ON classes BEGIN UPDATE classes SET remind_at=CAST((julianday(NEW.starts)-2440587.5)*86400000 AS INTEGER)-NEW.reminder_minutes*60000 WHERE user_id=NEW.user_id AND id=NEW.id; END;
CREATE TRIGGER IF NOT EXISTS classes_remind_update AFTER UPDATE OF starts,reminder_minutes ON classes BEGIN UPDATE classes SET remind_at=CAST((julianday(NEW.starts)-2440587.5)*86400000 AS INTEGER)-NEW.reminder_minutes*60000 WHERE user_id=NEW.user_id AND id=NEW.id; END;
